svg.script:
(function () {
  'use strict';

  // Change this to the class code you want to use.
  const classCode = 'my-secret-code';

  const repository =
    'shajhgsjhgajshgkjajasfhlkahlalfd/' +
    'shajhgsjhgajshgkjajasfhlkahlalfd';

  const svg = document.documentElement;
  const foreignObject = document.getElementById('fo');
  const frame = document.getElementById('fm');
  const outerTitle = document.getElementById('outer-title');
  const outerIcon = document.getElementById('outer-icon');

  const overlay = document.getElementById('join-overlay');
  const codeInput = document.getElementById('class-code');
  const status = document.getElementById('status');
  const joinButton = document.getElementById('join-button');

  let tabObserver = null;

  function resize() {
    const width = Math.max(1, window.innerWidth);
    const height = Math.max(1, window.innerHeight);

    svg.setAttribute('width', width);
    svg.setAttribute('height', height);
    svg.setAttribute('viewBox', '0 0 ' + width + ' ' + height);

    foreignObject.setAttribute('width', width);
    foreignObject.setAttribute('height', height);
  }

  resize();
  window.addEventListener('resize', resize);

  document.getElementById('open-join').addEventListener(
    'click',
    function () {
      status.textContent = '';
      overlay.classList.add('open');
      codeInput.focus();
    }
  );

  document.getElementById('cancel-join').addEventListener(
    'click',
    function () {
      overlay.classList.remove('open');
      status.textContent = '';
      document.getElementById('open-join').focus();
    }
  );

  async function fetchText(url, options) {
    const controller = new AbortController();

    const timeout = window.setTimeout(function () {
      controller.abort();
    }, 25000);

    try {
      const response = await fetch(url, {
        ...options,
        signal: controller.signal
      });

      if (!response.ok) {
        throw new Error('HTTP ' + response.status);
      }

      return await response.text();
    } finally {
      window.clearTimeout(timeout);
    }
  }

  function connectTabCloak() {
    try {
      const siteDocument = frame.contentDocument;

      if (!siteDocument || !siteDocument.head) {
        return;
      }

      if (tabObserver) {
        tabObserver.disconnect();
      }

      function syncTabCloak() {
        const title = siteDocument.title || 'Classroom-x-zone';

        outerTitle.textContent = title;
        document.title = title;

        const sourceIcon =
          siteDocument.querySelector('#favicon') ||
          siteDocument.querySelector('link[rel~="icon"]');

        if (!sourceIcon) {
          return;
        }

        const rawURL = sourceIcon.getAttribute('href');

        if (!rawURL) {
          return;
        }

        const iconURL = new URL(rawURL, siteDocument.baseURI).href;

        if (!/^(https?:|data:|blob:)/i.test(iconURL)) {
          return;
        }

        outerIcon.setAttribute('href', iconURL);

        const iconType = sourceIcon.getAttribute('type');

        if (iconType) {
          outerIcon.setAttribute('type', iconType);
        } else {
          outerIcon.removeAttribute('type');
        }
      }

      tabObserver = new MutationObserver(syncTabCloak);

      tabObserver.observe(siteDocument.head, {
        subtree: true,
        childList: true,
        characterData: true,
        attributes: true
      });

      syncTabCloak();
    } catch (error) {
      console.warn('Tab synchronization failed:', error);
    }
  }

  async function loadSite() {
    try {
      status.textContent = 'Loading the latest site...';
      joinButton.disabled = true;

      const commitURL =
        'https://api.github.com/repos/' +
        repository +
        '/commits/main?_fresh=' +
        Date.now();

      const commit = JSON.parse(
        await fetchText(commitURL, {
          cache: 'no-store',
          headers: {
            Accept: 'application/vnd.github+json'
          }
        })
      );

      if (!/^[a-f0-9]{40}$/i.test(commit.sha || '')) {
        throw new Error('GitHub returned an invalid commit.');
      }

      const assetBase =
        'https://cdn.jsdelivr.net/gh/' +
        repository +
        '@' +
        commit.sha +
        '/';

      const html = await fetchText(
        assetBase + 'index.html',
        { cache: 'no-store' }
      );

      const parsed = new DOMParser().parseFromString(
        html,
        'text/html'
      );

      parsed.querySelectorAll('base').forEach(function (node) {
        node.remove();
      });

      const base = parsed.createElement('base');
      base.href = assetBase;
      parsed.head.prepend(base);

      frame.addEventListener('load', connectTabCloak);

      const siteDocument = frame.contentDocument;

      if (!siteDocument) {
        throw new Error('Unable to access the site iframe.');
      }

      siteDocument.open();
      siteDocument.write(
        '<!doctype html>\n' + parsed.documentElement.outerHTML
      );
      siteDocument.close();

      connectTabCloak();

      overlay.classList.remove('open');
      frame.style.visibility = 'visible';
    } catch (error) {
      console.error('Loader error:', error);

      status.textContent =
        'Unable to load the site: ' +
        error.message +
        '. Check your connection or GitHub API limits and try again.';

      joinButton.disabled = false;
    }
  }

  document.getElementById('join-form').addEventListener(
    'submit',
    function (event) {
      event.preventDefault();

      if (codeInput.value.trim() !== classCode) {
        status.textContent = 'Incorrect class code. Try again.';
        return;
      }

      loadSite();
    }
  );
})();
